// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/healthz", wrapper.GetHealth)
	router.POST(options.BaseURL+"/auth/register", wrapper.Register)
	router.POST(options.BaseURL+"/auth/verify", wrapper.VerifyEmail)
	router.POST(options.BaseURL+"/auth/login", wrapper.Login)
	router.POST(options.BaseURL+"/auth/refresh", wrapper.RefreshSession)
	router.POST(options.BaseURL+"/auth/logout", wrapper.Logout)
	router.POST(options.BaseURL+"/auth/password-reset", wrapper.RequestPasswordReset)
	router.POST(options.BaseURL+"/auth/password-reset/confirm", wrapper.ConfirmPasswordReset)
	router.GET(options.BaseURL+"/me", wrapper.GetMe)
	router.GET(options.BaseURL+"/listings", wrapper.ListListings)
	router.POST(options.BaseURL+"/listings", wrapper.CreateListing)
	router.DELETE(options.BaseURL+"/listings/:id", wrapper.DeleteListing)
	router.GET(options.BaseURL+"/listings/:id", wrapper.GetListing)
	router.PATCH(options.BaseURL+"/listings/:id", wrapper.UpdateListing)
	router.POST(options.BaseURL+"/listings/:id/status", wrapper.SetListingStatus)
	router.GET(options.BaseURL+"/me/listings", wrapper.ListMyListings)
	router.GET(options.BaseURL+"/requests", wrapper.ListRequests)
	router.POST(options.BaseURL+"/requests", wrapper.CreateRequest)
	router.DELETE(options.BaseURL+"/requests/:id", wrapper.DeleteRequest)
	router.GET(options.BaseURL+"/requests/:id", wrapper.GetRequest)
	router.PATCH(options.BaseURL+"/requests/:id", wrapper.UpdateRequest)
	router.POST(options.BaseURL+"/requests/:id/status", wrapper.SetRequestStatus)
	router.GET(options.BaseURL+"/requests/:id/offers", wrapper.ListOffers)
	router.POST(options.BaseURL+"/requests/:id/offers", wrapper.CreateOffer)
	router.DELETE(options.BaseURL+"/offers/:id", wrapper.WithdrawOffer)
	router.GET(options.BaseURL+"/me/requests", wrapper.ListMyRequests)
}

